<script setup>
import RedesignTopbar from './RedesignTopbar.vue';
import { Head, Link, router, usePage } from '@inertiajs/vue3';
import { computed, ref } from 'vue';
import AdminSidebar from './AdminSidebar.vue';
const props = defineProps({ jobs: Object, jobItems: { type: Array, default: () => [] }, filters: Object });
const page = usePage();
const status = ref(props.filters?.status || 'all');
const search = ref(props.filters?.search || '');
const items = computed(() => props.jobItems.length ? props.jobItems : props.jobs?.data || []);
const applySearch = () => router.get(route('redesign.jobs'), { search: search.value || undefined, status: status.value === 'all' ? undefined : status.value }, { preserveState: true });
const setStatus = (value) => { status.value = value; applySearch(); };
const resetSearch = () => { search.value = ''; status.value = 'all'; router.get(route('redesign.jobs')); };
</script>
<template>
    <Head title="Job / program" />
    <div class="jobs-app"><AdminSidebar /><main><RedesignTopbar breadcrumb="Program & kelas" /><div class="content"><div v-if="page.props.flash?.message === 'JOB_CREATED' || page.props.flash?.message === 'JOB_UPDATED'" class="notice" role="status">{{ page.props.flash.message === 'JOB_CREATED' ? 'Job berhasil ditambahkan.' : 'Job berhasil diperbarui.' }}</div><div class="heading"><div><h1>Job / program</h1><p>Kelola program, status, emblem, dan jalur belajar.</p></div><Link class="primary" :href="route('redesign.jobs.create')">+ Tambah job</Link></div><div class="tabs" role="group" aria-label="Filter status"><button v-for="tab in [['all','Semua'],['active','Aktif'],['coming_soon','Segera hadir'],['draft','Draft'],['archive','Arsip']]" :key="tab[0]" :class="{ active: status === tab[0] }" @click="setStatus(tab[0])">{{ tab[1] }}</button></div><form class="filters" @submit.prevent="applySearch"><input v-model="search" aria-label="Cari program" placeholder="Cari nama, judul, atau kata kunci..." /><button type="submit">Filter</button><button type="button" @click="resetSearch">Reset</button></form><div class="job-grid"><article v-for="(job, index) in items" :key="job.id" class="job-card"><div class="card-top"><span class="number">{{ String(index + 1).padStart(2, '0') }}</span><span class="badge" :class="job.status">{{ status === 'archive' ? 'Arsip' : job.status === 'active' ? 'Aktif' : job.status === 'coming_soon' ? 'Segera hadir' : 'Draft' }}</span></div><h2>{{ job.name }}</h2><p>{{ job.users_count || 0 }} peserta · {{ job.study_groups_count || 0 }} kelas</p><div class="card-actions"><Link v-if="status !== 'archive'" :href="route('redesign.jobs.show', job.id)">Buka detail →</Link><Link v-if="status !== 'archive'" :href="route('redesign.jobs.edit', job.id)">Edit</Link></div></article><p v-if="!items.length" class="empty">Tidak ada program untuk filter ini.</p></div><nav v-if="props.jobs?.links?.length > 3" class="pagination" aria-label="Halaman program"><Link v-for="(link, index) in props.jobs.links" :key="index" :href="link.url || '#'" :class="{ active: link.active, disabled: !link.url }" v-html="link.label" /></nav></div></main></div>
</template>
